B='53电网火花.txt'
make('moheng','摩亨将军',B,
'摩亨将军是一个亚洲小国情报首脑在本次行动使用的代号，真正姓名连敌方情报机构也未掌握。他统率训练严密的特务，使用外观普通却具反潜鱼雷和飞弹设备的游艇，亲自推动一项巨型通电金属网计划。军工部门已经造出约一平方哩、十二吨重的合金网，却解决不了空中供电和升降问题，他便绑架安妮，利用她与云五风的感情逼专家合作。他能保持礼貌、提供良好待遇，也能马上把人质安危变成交易条件，甚至想让赶来救人的木兰花和穆秀珍执行最后任务。其办公处以玻璃隔开来访者，层层警卫和暗门保护自己，显示他并不靠个人武勇承担风险。他通过军官遭袭后的画像识破潜入者，这属于制度信息汇总而非全知。失去囚徒后，他的暴怒又压倒下属判断：众人不敢反驳他关于火车站不可能藏人的断言，逃亡者反而在那里等到援助。电网确被运往访问舰队上空，但情报泄露后护航飞机先击落一架运输机，整网失衡放电坠海，杀死大量鱼类而未达成屠杀舰队的目标。他仍是危险的权力人物，结局没有写其被推翻，军队规模也不能当作他随身拥有的超能力。',
'囚徒逃离，电网袭击被提前防备而失败；仍掌权，未见被捕或死亡。','情报组织、胁迫与大型武器项目指挥','通过国家军工、特务和飞机实施绑架与电网部署；本人判断情报并控制安全设施。','离不开国家设施、技术人员、飞机及供电；电网已在末次行动毁坏，重建不是即取即用，暴怒会压制正确报告。',[(582,692,'以安妮胁迫云五风及网的规模。'),(1012,1046,'代号、组织与武装游艇。'),(1196,1222,'供电和升降技术条件。'),(1772,1832,'识破画像、玻璃隔断与暗门。'),(2270,2276,'暴怒阻碍反对意见。'),(2406,2414,'电网实战失败。')],
'借秘密技术行动取得国家优势，把专家、亲情和下属生命都当作可控制的工具。',[('项目缺少技术答案','专家可被亲情牵制','扣住其珍视的人换取合作。'),('强敌进入自己的设施','已有警卫和隔断优势','以奖励和苦工营威胁迫其服务。'),('计划接连失控','不愿承认判断错误','怒斥惩处下属，可能使真实情况更难上报。')],roles=('反派',),scores=(2,0,2,3,3,3),tier='凶',ceiling='若另行配置完整军工电网、八架运输机、供电与护航，可尝试一平方哩范围导电杀伤；实际一次部署因单架运输机被击落连带失败，非个人常备能力。',destruction='本人为人类武装指挥者；完整电网项目的实战余波造成数十吨死鱼，计划对舰队人员的杀伤未实现。')
make('fudeli_colonel','佛德烈上校',B,
'佛德烈上校是某大国情报潜艇的负责人，奉命在水下跟踪摩亨将军的游艇。他从情报档案认识木兰花和穆秀珍，发现她们在追同一目标后，将她们带上潜艇，以照片和既有调查换取合作。他表面总带笑容，却清楚敌方游艇拥有反潜武器，也知道进入敌国领海一旦被发现，艇员会面临严重后果。穆秀珍把谨慎误当胆小，他仍能说明金属潜艇不可能伪装成普通大鱼，最终接受在敌方探测极限外保持距离的方案。他一度希望亲自上岸，认为自己是第一流间谍，但外貌和环境不利于隐蔽，便承担潜伏接应，提供潜水设备、通讯和港口观察。这个决定既帮助两名救援者深入，也让整艇冒险等待。后来海港巡逻队发现并逼潜艇浮出，艇员全部被俘，主角失去预定退路。他的失败并未使情报工作毫无意义：由救援获得的消息阻止了针对访问团与舰队的袭击。文末补充，经长期交涉他和部下在半年后获释，不能把终局停在永远囚禁，也不能把主角想象的严酷虐待写成逐项确证。他与卫斯理故事中的同译名少将缺少明确身份衔接，暂保持独立。',
'敌国海港被俘，半年后与艇员获释。','潜艇情报作业与协同接应','指挥水下跟踪、雷达和电视观察，调配潜水与通讯设备，传递已有调查材料。','需要实际潜艇和艇员；潜望摄影及近岸行动有暴露风险，不能跨越反潜侦测规则。',[(918,1046,'身份、合作与调查范围。'),(1230,1242,'反潜风险与距离。'),(1280,1388,'接应分工和潜入。'),(2286,2300,'被俘消息。'),(2394,2426,'贡献及获释终局。')],
'完成国家情报任务，也愿与有能力的平民合作，但必须在任务和艇员风险之间权衡。',[('遇到同追一目标的外部人员','资料显示可合作','交换必要情报并提出协同行动。'),('伙伴要求冒险接近','已知敌方探测能力','先说明具体危险，再选择可控距离。'),('个人能力被怀疑','任务又确需隐蔽分工','可能争取上阵，理解条件后也能承担接应。')],roles=('单书主角',),scores=(2,0,1,3,2,2),tier='并',uncertainties=['与卫斯理035国防部佛德烈少将仅有同译名和军职，未证同人。'])
make('li_major','李少校',B,
'李少校是摩亨将军侍卫班的副班长，在游艇停泊后独自留守。他具枪械、警戒和监视设备使用经验，木兰花潜入时，他发现异动并开枪，却在对方近身突入后被制。迫使他合作的不只是生命威胁，而是家属可能随自己受罚的恐惧。木兰花声称会把不合作的死亡布置成自杀，并利用其已经泄密的事实要求通行证，这场合作因此带有明确胁迫，不能写成他一开始就心甘情愿效忠主角。他提供首都兵工厂位置和保安证明，仍反复请求保守会面的秘密。后来三名逃亡者来电，他明知再次帮助难以隐瞒，还是取出将军特别通行证赶到火车站。他也带来潜艇已被俘的坏消息，迫使所有人重新寻找退路。特别证件每次使用都会被记录上报，使他清楚自己无法继续留任。木兰花提出以巨网阴谋的情报换取政治庇护，他遂接上妻子和婴儿，驾驶将军游艇离港，带全家登上接应飞机。最终提供的情报得到验证，阻止重大袭击。他的终局是脱离原机构求庇护，不再自动拥有侍卫权限、将军证件和军事舰艇的长期使用权。',
'携妻儿离境，以电网袭击情报取得接应并赴他国寻求政治庇护。','保安体系知识与证件、船只操作','熟悉将军办公室、通行证和岗哨程序，可驾驶车辆游艇并安排家属撤离。','原职务权限在叛离后失效；证件使用留有记录，需外部庇护与接应，不能单独调动外国空军。',[(1438,1470,'武装对抗、被制及家属威胁。'),(1490,1560,'职位、通行证和恐惧。'),(2282,2338,'接人、证件代价与全家出逃。'),(2340,2358,'游艇离港、情报换庇护。'),(2406,2410,'情报获验证。')],
'在严厉组织控制下保护自己与家属，合作一旦不可逆便为全家寻找真正退路。',[('被迫在保密与家属安危间选择','已无安全反抗机会','提供有限帮助并要求对方守密。'),('旧合作使自己有暴露风险','继续任职已难安全','愿再次援助并评估共同逃亡。'),('获得可交换的关键情报','能换得可信庇护','带家属撤离，放弃原有职位。')],roles=('阶段性对立者','单书主角'),scores=(3,0,1,3,3,3),tier='并')
make('agent_220','二二〇',B,
'二二〇是摩亨将军手下的情报人员，正文只给出数字代号，没有确认本名。他在绑架安妮的行动中承担船舱看守，讨论过以安妮迫使云五风前来的计划，也知道组织已经调查两人的感情。安妮中麻醉针后醒来，选择暂时装作昏迷，趁他背转身夺枪；二二〇反应很快，几乎同时压住她手背，但被她借床沿蹬中小腹，最终成了人质。他在枪口下显得愤怒尴尬，却仍试图保持职业镇定，说做这一行已不把死亡当大事，劝对方放下枪谈判。他的胆量并不改变实际处境：安妮能够暂时控制他，却无法靠一个普通成员迫使整个组织释放自己，二二〇也没有资格独自决定交易。云五风答应合作后，组织开放舱门让安妮离开，她推倒其椅子发泄愤怒，他立即翻滚出舱，显示危急时仍会主动寻找生存机会。此后正文未单独交代其去向，不能与后来被关押的无名警卫、李少校或其他编号特务合并。终局保留行动失败与组织工具身份，不把他的职业话术理解成恐惧免疫或愿意无条件自毁的精神设定。',
'看守中被安妮夺枪挟持，释放时翻滚脱离船舱；后续未单独交代。','特务警戒与近身争夺','能观察人质、迅速争夺枪械，熟悉以感情胁迫目标的组织计划。','警戒仍会失误；身体可被踢击和枪械威胁，职级不足以独自改变上级决定。',[(430,448,'行动计划与警戒讨论。'),(464,528,'夺枪失败、代号和职业说辞。'),(588,592,'将军确认其身份。'),(704,718,'被推倒后滚出船舱。')],
'执行上级的绑架任务，并在受制后用职业镇定和谈判维护局面。',[('人质似乎仍昏迷','未及时确认恢复程度','可能因短暂背转身失去主动。'),('自己被枪口控制','仍相信组织目标会完成','保持言语镇定并试图引导谈判。'),('出现脱离枪口的机会','无需继续维持体面','迅速翻滚或撤出以保命。')],roles=('反派',),aliases=('二二○','二二零'),scores=(3,0,0,2,2,2),tier='并')
cov(B,[('摩亨将军','moheng','反派','绑架专家、武器阴谋和囚禁。'),('佛德烈上校','fudeli_colonel','单书主角','潜艇追踪、接应、被俘和获释。'),('李少校','li_major','阶段性对立者','留守抵抗后受迫合作、携家属出逃。'),('二二〇','agent_220','反派','具代号人质看守。'),('穆秀珍','mulanhua_mu_xiuzhen','系列主角','潜入与共同救援。'),('安妮','mulanhua_annie','系列主角','被绑、夺枪及释放。'),('云五风','mulanhua_yun_wufeng','跨书重要配角','被迫技术合作并获救。'),('高翔','mulanhua_gao_xiang','系列主角','联络与回国迎接。'),('方局长','mulanhua_fang_director','跨书重要配角','协调警务和领事。'),('云四风','mulanhua_yun_sifeng','跨书重要配角','接讯提前从欧洲返回。')],excluded=[('无名守卫上校、军官、领事、李少校妻儿及国家领袖','警戒、通报、家属或政治背景，缺乏独立人物线；守卫被上级当通敌者并不证明其实际叛变。')],notes=['政治国家与真实身份未明，按小说匿名背景保留。','电网的技术描述按小说机制存档，不作现实工程可靠性的保证；运输机与大型供电装备不是任何人物随身能力。'])
